// Export a self-contained HTML player; no external runtime, fonts or image URLs.
export function standalonePreview(project,code){
 const data=JSON.stringify(project).replaceAll('<','\\u003c');
 return `<!doctype html><html lang="vi"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Map preview</title>
<style>body{margin:0;background:#10161e;color:#d3ed92;font:14px system-ui;display:flex;flex-direction:column;height:100dvh}header{padding:8px;display:flex;gap:8px;align-items:center;flex-wrap:wrap}button,select{padding:10px;background:#223343;color:inherit;border:1px solid #52677b;border-radius:6px;touch-action:none;font:inherit}canvas{flex:1;min-height:0;width:100%;touch-action:none}nav{padding:8px;text-align:center}#note{font-size:12px}input[type=range]{max-width:120px}</style>
<header><span id="name"></span><button id="reset">Về spawn</button><select id="mode" aria-label="Ngày / đêm"><option value="day">☀ Ngày</option><option value="night">☾ Đêm</option><option value="time">◷ Theo giờ</option></select><label>Giờ <input id="hour" type="range" min="0" max="23.75" step="0.25"><output id="hourLabel"></output></label><button id="original">Ánh sáng đã lưu</button><label><input id="col" type="checkbox">Vùng cản</label><span id="note"></span></header>
<canvas></canvas><nav><button data-dir="up">↑</button><button data-dir="left">←</button><button data-dir="down">↓</button><button data-dir="right">→</button></nav><script type="module">${code}
const player=await DarkinMapPlayer.load(${data}),cv=document.querySelector('canvas'),ctx=cv.getContext('2d'),pressed=new Set(),$=id=>document.getElementById(id),saved=lightingSettings(player.project);
$('name').textContent=player.project.name;
function lightUI(){const l=lightingSettings(player.project);$('mode').value=l.mode;$('hour').value=l.hour;$('hour').disabled=l.mode!=='time';$('hourLabel').textContent=l.hour+' h'}lightUI();
$('mode').onchange=()=>{player.project.lighting={...lightingSettings(player.project),mode:$('mode').value};lightUI()};$('hour').oninput=()=>{player.project.lighting={...lightingSettings(player.project),hour:Number($('hour').value)};lightUI()};$('original').onclick=()=>{player.project.lighting={...saved};lightUI()};
$('reset').onclick=()=>player.actor={...player.project.spawn,radius:12};
for(const b of document.querySelectorAll('[data-dir]')){b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);pressed.add(b.dataset.dir)};for(const ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,()=>pressed.delete(b.dataset.dir))}
window.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','w','a','s','d'].includes(e.key)){e.preventDefault();pressed.add(e.key)}});window.addEventListener('keyup',e=>pressed.delete(e.key));window.addEventListener('blur',()=>pressed.clear());
let last=0;function frame(t){const dt=Math.min(.1,(t-last)/1000);last=t;const r=cv.getBoundingClientRect(),d=devicePixelRatio||1,w=Math.round(r.width*d),h=Math.round(r.height*d);if(cv.width!==w||cv.height!==h){cv.width=w;cv.height=h}ctx.setTransform(d,0,0,d,0,0);const yes=(...names)=>names.some(n=>pressed.has(n)),warp=player.update(dt,Number(yes('right','ArrowRight','d'))-Number(yes('left','ArrowLeft','a')),Number(yes('down','ArrowDown','s'))-Number(yes('up','ArrowUp','w')));$('note').textContent=warp?'Cửa '+warp.id+' → '+warp.to+' / '+warp.at+' (game cần nạp map đích)':'WASD / phím mũi tên hoặc các nút hướng';player.draw(ctx,r.width,r.height,{zoom:.65,collision:$('col').checked,markers:true});requestAnimationFrame(frame)}requestAnimationFrame(frame);
<\/script></html>`;
}
